1	/**
2	 * Server component for rendering JSON-LD structured data.
3	 *
4	 * Follows React best practices for dangerouslySetInnerHTML:
5	 * - Creates sanitized data object separately (not inline)
6	 * - Escapes </script> and < to prevent XSS
7	 * - Data comes from server-side API responses, not user input
8	 *
9	 * @see https://react.dev/reference/react-dom/components/common#dangerously-setting-the-inner-html
10	 */
11	export default function JsonLdServer({
12	  id,
13	  data,
14	}: {
15	  id?: string;
16	  data?: unknown;
17	}) {
18	  // No headers() needed - relaxed CSP allows inline scripts for ISR/PPR compatibility
19	
20	  // Generate JSON string from data
21	  const json = JSON.stringify(data ?? {});
22	
23	  // Escape </script> and < to prevent XSS in JSON-LD scripts
24	  // Order matters: escape </script> first, then any remaining < characters
25	  // This is safe because data comes from server-side API responses, not user input
26	  const sanitizedHtml = json
27	    .replace(/<\/script>/gi, "\\u003c/script\\u003e")
28	    .replace(/</g, "\\u003c");
29	
30	  // Create sanitized data object separately (React best practice)
31	  // Per React docs: "You should only create the object with the __html key close to where HTML is generated"
32	  const sanitizedData = { __html: sanitizedHtml };
33	
34	  return (
35	    <script
36	      id={id}
37	      type="application/ld+json"
38	      suppressHydrationWarning={true}
39	      dangerouslySetInnerHTML={sanitizedData}
40	    />
41	  );
42	}
